<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --card: #ffffff;
        --text: #172033;
        --muted: #667085;
        --border: #d9e2ec;
        --primary: #2563eb;
        --primary-dark: #1d4ed8;
        --error: #dc2626;
        --success: #047857;
        --shadow: 0 24px 70px rgba(23, 32, 51, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.16), transparent 34rem),
          linear-gradient(135deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

      .page-shell {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 3rem 1rem;
      }

      .support-card {
        width: min(100%, 560px);
        padding: clamp(1.5rem, 4vw, 2.5rem);
        border: 1px solid rgba(217, 226, 236, 0.85);
        border-radius: 28px;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        margin-bottom: 1rem;
        padding: 0.4rem 0.75rem;
        border-radius: 999px;
        background: #eaf1ff;
        color: var(--primary-dark);
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 6vw, 3rem);
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.65;
      }

      form {
        display: grid;
        gap: 1.15rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        font-size: 0.92rem;
        font-weight: 700;
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        border-radius: 14px;
        padding: 0.9rem 1rem;
        background: #fff;
        color: var(--text);
        font: inherit;
        outline: none;
        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      }

      input::placeholder {
        color: #98a2b3;
      }

      input:focus {
        border-color: var(--primary);
        box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
      }

      input[aria-invalid="true"] {
        border-color: var(--error);
      }

      .helper-text,
      .validation-message {
        margin: 0;
        font-size: 0.85rem;
        line-height: 1.4;
      }

      .helper-text {
        color: var(--muted);
      }

      .validation-message {
        color: var(--error);
        font-weight: 600;
      }

      .success-message {
        display: none;
        margin: 0;
        padding: 0.9rem 1rem;
        border-radius: 14px;
        background: #ecfdf5;
        color: var(--success);
        font-weight: 700;
      }

      .success-message.is-visible {
        display: block;
      }

      button {
        margin-top: 0.4rem;
        border: 0;
        border-radius: 14px;
        padding: 0.95rem 1.25rem;
        background: linear-gradient(135deg, var(--primary), #4f46e5);
        color: #fff;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 14px 32px rgba(37, 99, 235, 0.3);
        transition: transform 160ms ease, box-shadow 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 36px rgba(37, 99, 235, 0.36);
      }

      button:focus-visible {
        outline: 4px solid rgba(37, 99, 235, 0.22);
        outline-offset: 3px;
      }
    </style>
  </head>
  <body>
    <main id="app"></main>

    <script>
      const formState = {
        fullName: "",
        email: "",
        phone: "",
      };

      const touchedFields = {
        fullName: false,
        email: false,
        phone: false,
      };

      const validators = {
        fullName(value) {
          return value.trim() ? "" : "Full name is required.";
        },
        email(value) {
          const email = value.trim();

          if (!email) {
            return "Email address is required.";
          }

          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
            ? ""
            : "Enter a valid email address.";
        },
        phone(value) {
          const phone = value.trim();

          if (!phone) {
            return "";
          }

          return /^\+?[0-9][0-9\s().-]{6,19}$/.test(phone)
            ? ""
            : "Enter a phone number in the expected format.";
        },
      };

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#039;");
      }

      function getErrors() {
        return {
          fullName: validators.fullName(formState.fullName),
          email: validators.email(formState.email),
          phone: validators.phone(formState.phone),
        };
      }

      function TextInput({ id, label, type = "text", placeholder, required = false, helperText, error }) {
        const helperId = helperText ? `${id}-helper` : "";
        const errorId = error ? `${id}-error` : "";
        const describedBy = [helperId, errorId].filter(Boolean).join(" ");
        const safeValue = escapeHtml(formState[id]);

        return `
          <div class="form-field">
            <label for="${id}">${escapeHtml(label)}${required ? " *" : ""}</label>
            <input
              id="${id}"
              name="${id}"
              type="${escapeHtml(type)}"
              placeholder="${escapeHtml(placeholder)}"
              value="${safeValue}"
              ${required ? "required" : ""}
              aria-invalid="${Boolean(error)}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            />
            ${helperText ? `<p class="helper-text" id="${helperId}">${escapeHtml(helperText)}</p>` : ""}
            ${error ? `<p class="validation-message" id="${errorId}">${escapeHtml(error)}</p>` : ""}
          </div>
        `;
      }

      function ContactForm() {
        const errors = getErrors();
        const visibleErrors = Object.fromEntries(
          Object.entries(errors).map(([field, error]) => [field, touchedFields[field] ? error : ""])
        );

        return `
          <section class="support-card" aria-labelledby="support-heading">
            <span class="eyebrow">Support request</span>
            <h1 id="support-heading">How can we help?</h1>
            <p class="intro">
              Send our support team your contact details and we will follow up with the next best step.
            </p>

            <form id="support-form" novalidate>
              ${TextInput({
                id: "fullName",
                label: "Full name",
                placeholder: "Alex Morgan",
                required: true,
                error: visibleErrors.fullName,
              })}
              ${TextInput({
                id: "email",
                label: "Email address",
                type: "email",
                placeholder: "alex@example.com",
                required: true,
                error: visibleErrors.email,
              })}
              ${TextInput({
                id: "phone",
                label: "Phone number",
                type: "tel",
                placeholder: "+1 555 123 4567",
                helperText: "Optional. Use country code and 7-20 digits, for example +1 555 123 4567.",
                error: visibleErrors.phone,
              })}
              <p class="success-message" id="success-message" role="status">
                Thanks, your support request is ready to send.
              </p>
              <button type="submit">Submit request</button>
            </form>
          </section>
        `;
      }

      function App() {
        return `<div class="page-shell">${ContactForm()}</div>`;
      }

      function render() {
        document.querySelector("#app").innerHTML = App();
        bindEvents();
      }

      function bindEvents() {
        const form = document.querySelector("#support-form");
        const successMessage = document.querySelector("#success-message");

        ["fullName", "email", "phone"].forEach((field) => {
          const input = document.querySelector(`#${field}`);

          input.addEventListener("input", (event) => {
            formState[field] = event.target.value;
            successMessage.classList.remove("is-visible");
            render();
            document.querySelector(`#${field}`).focus();
          });

          input.addEventListener("blur", () => {
            touchedFields[field] = true;
            render();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          Object.keys(touchedFields).forEach((field) => {
            touchedFields[field] = true;
          });

          const hasErrors = Object.values(getErrors()).some(Boolean);
          render();

          if (!hasErrors) {
            document.querySelector("#success-message").classList.add("is-visible");
          }
        });
      }

      render();
    </script>
  </body>
</html>
