AssistantMessageToolRequest(name='bash', tool_call_id='call_CqELXFmSQj3scgtJOd4AjWwh', arguments={'command': 'node - <<'NODE'
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
new Function(script);
const rendered = new Function(script.replace(/\n\s*render\(\);\s*$/, '\nreturn App();'))();
const inputs = [...rendered.matchAll(/<input[\s\S]*?\/>/g)].map((match) => match[0]);
const inputById = (id) => inputs.find((input) => input.includes(`id="${id}"`)) || '';
const checks = {
  standaloneDocument: html.includes('<!DOCTYPE html>') && html.includes('<html lang="en">'),
  renderedFormFields: (rendered.match(/class="form-field"/g) || []).length === 3,
  fullNameRequired: /\srequired(\s|>|$)/.test(inputById('fullName')),
  emailRequired: /\srequired(\s|>|$)/.test(inputById('email')),
  phoneOptional: inputById('phone').includes('id="phone"') && !/\srequired(\s|>|$)/.test(inputById('phone')),
  phoneHelper: rendered.includes('Optional. Use country code and 7-20 digits'),
  submitButton: rendered.includes('<button type="submit">Submit request</button>'),
  inlineValidation: rendered.includes('aria-invalid') && html.includes('validation-message'),
};
console.log(JSON.stringify(checks, null, 2));
if (Object.values(checks).some((value) => value !== true)) process.exit(1);
